<?php
namespace App\Tests\Builder;
use App\Builder\ProgramBuilderService;
use App\Entity\{BuilderEntity,BuilderField};
use App\Runtime\RuntimeHttpException;
use PHPUnit\Framework\TestCase;
final class SignedRangeBuilderTest extends TestCase {
 private function valid():array{return[['field'=>'fornecedor_id','required'=>true,'filter'=>true,'readonly'=>true,'createDefault'=>false,'integerRange'=>['min'=>-2147483648,'max'=>2147483647]]];}
 private function normalize(array $contexts,array $profile=[],string $entityCode='descontos_importacao_fornecedor_progress',string $type='integer',bool $pk=false,string $page='crud',string $fieldCode='fornecedor_id',array $options=[]):array{$profile+=['programCode'=>'op1056','screenId'=>'ciw.descontos-importacao-fornecedor','allowCreate'=>false,'allowUpdate'=>false,'allowDelete'=>false];$entity=(new BuilderEntity())->setCode($entityCode)->setEntityType('api');$entity->addField((new BuilderField())->setCode($fieldCode)->setDataType($type)->setPrimaryKey($pk)->setOptions($options));$entity->addField((new BuilderField())->setCode('record_key')->setDataType('string')->setPrimaryKey(true));$r=new \ReflectionClass(ProgramBuilderService::class);return$r->getMethod('normalizeContextFields')->invoke($r->newInstanceWithoutConstructor(),$contexts,$entity,$page,$profile);}
 public function testClosedReadonlySupplierProfileAcceptsFullAndBoundedSignedRanges():void{foreach([[-2147483648,2147483647],[0,0],[-10,-1],[7,7]]as[$min,$max]){$value=$this->valid();$value[0]['integerRange']=['min'=>$min,'max'=>$max];self::assertSame($value,$this->normalize($value));}}
 public function testNoRangeAndFilterOnlyPriorBehaviorPreserved():void{$value=$this->valid();unset($value[0]['integerRange']);self::assertSame($value,$this->normalize($value));$value[0]=['field'=>'fornecedor_id','required'=>false,'filter'=>true,'readonly'=>true,'createDefault'=>false,'filterOnly'=>true];self::assertSame($value,$this->normalize($value));}
 public function testInvalidShapesTypesBoundsAndFlagsFailClosed():void{foreach([null,[],['min'=>0],['max'=>10],['min'=>0,'max'=>10,'other'=>true],['min'=>'0','max'=>10],['min'=>false,'max'=>10],['min'=>0.5,'max'=>10],['min'=>-2147483649,'max'=>10],['min'=>0,'max'=>2147483648],['min'=>1,'max'=>0]]as$range){$bad=$this->valid();$bad[0]['integerRange']=$range;try{$this->normalize($bad);self::fail('Invalid range accepted');}catch(RuntimeHttpException $error){self::assertSame(422,$error->getStatusCode());}}foreach(['required'=>false,'readonly'=>false,'filter'=>false,'createDefault'=>true,'unknown'=>true]as$key=>$value){$bad=$this->valid();$bad[0][$key]=$value;try{$this->normalize($bad);self::fail('Invalid flags accepted');}catch(RuntimeHttpException $error){self::assertSame(422,$error->getStatusCode());}}}
 public function testGenericFrameworkAcceptsRenamedFieldEntityProgramAndScreen():void{$value=$this->valid();$value[0]['field']='scope_id';self::assertSame($value,$this->normalize($value,['programCode'=>'cd0199','screenId'=>'neutral.readonly'],'neutral_scope','integer',false,'crud','scope_id'));}
 public function testUnsupportedRemoteOptionsAndFileConsumersFailClosed():void{foreach([['api'=>['optionsSource'=>['operationCode'=>'closed']]],['attachment'=>[]],['editor'=>'file']]as$options){try{$this->normalize($this->valid(),[],options:$options);self::fail('Unsupported consumer accepted');}catch(RuntimeHttpException $e){self::assertSame(422,$e->getStatusCode());}}}
 public function testWriterFieldTypePkOrProcessRejected():void{foreach([[['allowCreate'=>true],'descontos_importacao_fornecedor_progress','integer',false,'crud'],[[],'descontos_importacao_fornecedor_progress','string',false,'crud'],[[],'descontos_importacao_fornecedor_progress','integer',true,'crud'],[[],'descontos_importacao_fornecedor_progress','integer',false,'process']]as[$profile,$entity,$type,$pk,$page]){try{$this->normalize($this->valid(),$profile,$entity,$type,$pk,$page);self::fail('Wrong scope accepted');}catch(RuntimeHttpException $error){self::assertSame(422,$error->getStatusCode());}}}
}
